// Reference solution
function wireBytes(msgBytes, mss) {
  var segments = Math.ceil(msgBytes / mss);
  return { segments: segments, totalBytes: msgBytes + segments * (20 + 20 + 18), lastSegment: msgBytes - (segments - 1) * mss };
}
